script:
test("work submitted exactly at the deadline keeps its raw score", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704067200000}), {periodsLate: 0, deduction: 0, score: 45});
});
test("work submitted one millisecond before the deadline is not penalised", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 80, rawScore: 33, deadline: 1735689600000, submittedAt: 1735689599999}), {periodsLate: 0, deduction: 0, score: 33});
});
test("one hour late is one period and deducts ten percent of the maximum", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50.0, rawScore: 45, deadline: 1706659200000, submittedAt: 1706662800000.0}), {periodsLate: 1, deduction: 5, score: 40});
});
test("one millisecond late starts the first period", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 30, rawScore: 22, deadline: 1706745600000, submittedAt: 1706745600001}), {periodsLate: 1, deduction: 3, score: 19});
});
test("just under twenty four hours late stays in the first period", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 30, rawScore: 22, deadline: 1706745600000, submittedAt: 1706831999999}), {periodsLate: 1, deduction: 3, score: 19});
});
test("exactly twenty four hours late does not start the next period", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 30, rawScore: 22, deadline: 1706745600000, submittedAt: 1706832000000}), {periodsLate: 1, deduction: 3, score: 19});
});
test("one millisecond past twenty four hours starts the second period", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 30, rawScore: 22, deadline: 1706745600000, submittedAt: 1706832000001}), {periodsLate: 2, deduction: 6, score: 16});
});
test("forty nine hours late is three periods and deducts fifteen points", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45.0, deadline: 1733011200000, submittedAt: 1733187600000}), {periodsLate: 3, deduction: 15, score: 30});
});
test("a penalty larger than the raw score floors the score at zero and deducts only the raw score", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 10, deadline: 1709164800000, submittedAt: 1709424000000}), {periodsLate: 3, deduction: 10, score: 0});
});
test("exactly one hundred twenty hours late is five periods and scores twenty", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1735603200000, submittedAt: 1736035200000}), {periodsLate: 5, deduction: 25, score: 20});
});
test("one millisecond under one hundred twenty hours late is still five periods", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1735603200000, submittedAt: 1736035199999}), {periodsLate: 5, deduction: 25, score: 20});
});
test("one hundred twenty hours and one minute late is six periods and scores zero", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1735603200000, submittedAt: 1736035260000}), {periodsLate: 6, deduction: 45, score: 0});
});
test("twenty four hours and one minute late is two periods", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 40, rawScore: 28, deadline: 1709186400000, submittedAt: 1709272860000}), {periodsLate: 2, deduction: 8, score: 20});
});
test("a raw score of zero stays zero and removes no points", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 0, deadline: 1704067200000, submittedAt: 1704070800000}), {periodsLate: 1, deduction: 0, score: 0});
});
test("exactly ninety six hours late counts as four periods", function () {
  assert.equal(code.countLatePeriods({deadline: 1733011200000, submittedAt: 1733356800000}), 4);
});
test("an unknown field throws an error naming that field", function () {
  assert.throws(function () {
    code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704067200000, bonus: 1});
  }, /unknown field: bonus/);
});
